#!/usr/bin/env python3
"""
到院提醒「当前提醒」置顶 + 撤销（原因 + 工号，记录全程留存）补丁
visit_reminder_top_banner_revoke_patch

前置条件：先应用 demo_ux_fixes_patch（到院提醒横幅基础补丁）。

用法（项目根目录）：
    python3 scripts/apply_visit_reminder_top_banner_revoke_patch.py "$PWD"

改动（仅前端，后端撤销接口已留存 revokedAt/revokedBy/revokeReason 及审计）：
  - 将「当前到院提醒」横幅移动到到院提醒页顶部（与电话随访“下次随访时间”一致）。
  - 横幅内新增「撤销提醒」按钮；撤销需填写原因 + 工号 / 电子签名。
  - 撤销复用既有 /hospital-visit-reminders/:id/revoke 接口，记录全程留存。

可安全重复运行：已应用的改动会被跳过；若文件与基线不符则中止且不修改任何文件。
"""
import base64
import json
import sys
from collections import OrderedDict
from pathlib import Path

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path.cwd().resolve()
EDITS = json.loads(base64.b64decode("").decode("utf-8"))

by_file = OrderedDict()
for e in EDITS:
    by_file.setdefault(e["file"], []).append(e)

missing = [rel for rel in by_file if not (root / rel).exists()]
if missing:
    raise SystemExit("找不到以下文件，请在项目根目录（包含 apps/ 的目录）运行：\n  " + "\n  ".join(missing))

# Prerequisite: demo_ux_fixes_patch must already be applied (it is what creates
# the "当前到院提醒" banner this patch builds on).
VISIT = "apps/web/src/components/PatientHospitalVisitTab.tsx"
visit_text = (root / VISIT).read_text(encoding="utf-8")
if ("renderVisitReminderBanner" not in visit_text
        and "Unified with the phone follow-up" not in visit_text):
    raise SystemExit(
        "前置补丁未应用：请先应用 demo_ux_fixes_patch（到院提醒横幅基础补丁），再运行本补丁。\n"
        "未修改任何文件。"
    )


def apply_one(text, e, label):
    sig, kind = e["sig"], e["kind"]
    already = (sig in text) if kind == "present" else (sig not in text)
    if already:
        return text, False
    if e["old"] in text:
        return text.replace(e["old"], e["new"], 1), True
    raise SystemExit(f"[{label}] 未找到预期代码，且补丁内容也不存在；文件可能已与基线不同，未修改任何文件。")


results, report = OrderedDict(), OrderedDict()
for rel, edits in by_file.items():
    text = (root / rel).read_text(encoding="utf-8")
    a = s = 0
    for i, e in enumerate(edits, 1):
        text, did = apply_one(text, e, f"{rel} #{i}")
        a += int(did); s += int(not did)
    results[rel] = text
    report[rel] = (a, s)

for rel, text in results.items():
    (root / rel).write_text(text, encoding="utf-8")

print("补丁已应用（已应用 / 已存在）：")
for rel, (a, s) in report.items():
    print(f"  {rel}: {a} applied, {s} already present")
print("\n完成。请按常规方式重新构建前端进行验证。")
